import random,itertools,time
P={'a':['x','y','z'],'b':['y','x','z'],'c':['x','y','z']}; R={'x':['b','a','c'],'y':['a','b','c'],'z':['a','b','c']}
m=stable_matching(P,R); assert m=={'a':'x','b':'y','c':'z'} and is_stable(m,P,R) and blocking_pairs(m,P,R)==[]
bad={'a':'z','b':'y','c':'x'}; assert not is_stable(bad,P,R) and blocking_pairs(bad,P,R)==[('a','x'),('a','y')]
random.seed(41)
for _ in range(40):
    n=random.randint(1,6); ps=[f'p{i}' for i in range(n)]; rs=[f'r{i}' for i in range(n)]
    P={p:random.sample(rs,n) for p in ps}; R={r:random.sample(ps,n) for r in rs}
    m=stable_matching(P,R); assert sorted(m)==ps and sorted(m.values())==rs and is_stable(m,P,R)
    best={p:None for p in ps}
    for perm in itertools.permutations(rs):
        mm=dict(zip(ps,perm))
        if is_stable(mm,P,R):
            for p in ps:
                if best[p] is None or P[p].index(mm[p])<P[p].index(best[p]): best[p]=mm[p]
    assert m==best, 'not proposer-optimal'
random.seed(42); n=2000; ps=list(range(n)); rs=list(range(n,2*n))
P={p:random.sample(rs,n) for p in ps}; R={r:random.sample(ps,n) for r in rs}
t0=time.time(); m=stable_matching(P,R); assert time.time()-t0<20 and is_stable(m,P,R)
